-- Tighten over-long cloze blanks (169 cards)
-- Shortens definition/clause blanks to recallable terms. Safe to re-run (keyed by id).
BEGIN;

UPDATE public.flashcards SET cloze_text = $praxfix$Classical cell theory's four claims: living things are made of {{c1::cells}}; the cell is life's smallest {{c2::living unit}}; every cell arises from a {{c3::pre-existing cell}}; and {{c4::DNA}} carries hereditary information to the next generation.$praxfix$, cloze_count = 4 WHERE id = '11ada154-4cc6-4151-9d11-435dc108a9da';
UPDATE public.flashcards SET cloze_text = $praxfix$Lacking ribosomes, the {{c1::smooth endoplasmic reticulum}} handles {{c2::lipid and steroid synthesis}} and {{c3::detoxification}} of drugs and metabolic byproducts.$praxfix$, cloze_count = 3 WHERE id = '65dbb712-2ba1-4ffc-a9b0-05a2c9af1b47';
UPDATE public.flashcards SET cloze_text = $praxfix$Enveloped viruses enter the host by {{c1::membrane fusion}}, releasing the capsid into the cytoplasm; non-enveloped viruses are typically taken up by {{c2::receptor-mediated endocytosis}}.$praxfix$, cloze_count = 2 WHERE id = 'c3942e52-6d18-4de1-97af-f512de31f24a';
UPDATE public.flashcards SET cloze_text = $praxfix$Compared with the active metals, transition metals are notably {{c1::harder}} and {{c2::denser}}, with higher {{c3::melting and boiling points}}, yet remain malleable and excellent conductors thanks to delocalized d-electrons.$praxfix$, cloze_count = 3 WHERE id = 'dbedae99-4310-4e0e-bf65-4120c4e40d14';
UPDATE public.flashcards SET cloze_text = $praxfix${{c1::IUPAC nomenclature}} is organic chemistry's systematic naming convention; a name maps to one unique structure, encoding the molecule's {{c2::connectivity}}, {{c3::functional groups}}, and {{c4::substituent positions}}.$praxfix$, cloze_count = 4 WHERE id = 'f704d736-def2-4677-abd4-bb289bfb25c2';
UPDATE public.flashcards SET cloze_text = $praxfix$IUPAC naming, in order: (1) find the {{c1::longest carbon chain}} containing the highest-priority group; (2) set the {{c2::suffix}}; (3) number for the {{c3::lowest locant}}; (4) name and alphabetize the {{c4::substituents}}.$praxfix$, cloze_count = 4 WHERE id = 'e1696031-6013-47e7-9cd3-99efdf72e2c7';
UPDATE public.flashcards SET cloze_text = $praxfix$The two {{c1::acidic}} amino acids (negatively charged at physiological pH) are {{c2::aspartate (Asp/D)}} and {{c2::glutamate (Glu/E)}}, each with a deprotonated side-chain carboxylate.$praxfix$, cloze_count = 2 WHERE id = '811d0851-3b19-42f6-b7b0-eaf01bf9675d';
UPDATE public.flashcards SET cloze_text = $praxfix$The three {{c1::basic}} amino acids (positively charged at physiological pH) are {{c2::lysine (Lys/K)}}, {{c2::arginine (Arg/R)}}, and {{c2::histidine (His/H)}}.$praxfix$, cloze_count = 2 WHERE id = 'f91f004a-6035-467e-99f8-d54e9b4b98de';
UPDATE public.flashcards SET cloze_text = $praxfix${{c1::Proline}} is structurally unique: its side chain loops back to bond with the {{c2::α-amino nitrogen}}, forming a five-membered ring. This rigidity introduces {{c3::kinks}} and disrupts α-helices and β-pleated sheets.$praxfix$, cloze_count = 3 WHERE id = '2e5ade74-2585-43d4-8eb4-16fff7884ddd';
UPDATE public.flashcards SET cloze_text = $praxfix$In a pulley system, mechanical advantage equals the number of {{c1::rope segments}} directly supporting the load. Two supporting ropes give MA = 2; four give MA = 4.$praxfix$, cloze_count = 1 WHERE id = '9c44f242-b561-451b-9f20-df90a4882fbd';
UPDATE public.flashcards SET cloze_text = $praxfix$A {{c1::scalar}} is a physical quantity with {{c2::magnitude only}} — no direction. Examples: distance, speed, mass, energy, and pressure.$praxfix$, cloze_count = 2 WHERE id = '96aadd80-438b-47aa-9326-324694289b47';
UPDATE public.flashcards SET cloze_text = $praxfix$In the {{c1::tip-to-tail}} method, each vector is placed so its tail begins at the previous vector's tip, preserving magnitude and direction. The {{c2::resultant vector}} then runs from the first tail to the last tip.$praxfix$, cloze_count = 2 WHERE id = '67eb7343-55b4-4f4f-bd4a-d6d713d2c6a8';
UPDATE public.flashcards SET cloze_text = $praxfix$For any given pair of surfaces, the coefficient of static friction is always {{c1::greater than}} the coefficient of kinetic friction ({{c2::μₛ > μₖ}}). That is why it takes more force to start an object sliding than to keep it sliding.$praxfix$, cloze_count = 2 WHERE id = '49963991-2402-436f-b3a7-625d3d3cf7b5';
UPDATE public.flashcards SET cloze_text = $praxfix${{c1::Friction}} is a contact force that opposes the {{c2::relative motion}} (or attempted motion) of surfaces in contact; it always acts along the contact surface, never perpendicular to it.$praxfix$, cloze_count = 2 WHERE id = '363029e7-763a-43e3-93e2-11f0424f1b35';
UPDATE public.flashcards SET cloze_text = $praxfix$Gravitational potential energy is always measured relative to a chosen {{c1::reference level (datum)}}. Only differences in PE are physically meaningful — ΔU = mgΔh is independent of where you set zero.$praxfix$, cloze_count = 1 WHERE id = 'd9ac1eea-b634-470f-abde-e404fc2dca55';
UPDATE public.flashcards SET cloze_text = $praxfix$In a substituted cyclohexane, the preferred chair conformation places the larger substituent {{c1::equatorial}}, minimizing the {{c2::1,3-diaxial strain}} a bulky axial group would have with the axial hydrogens on the same face.$praxfix$, cloze_count = 2 WHERE id = '895cd87b-5c0f-4520-a452-8d2c3282aff3';
UPDATE public.flashcards SET cloze_text = $praxfix$One enantiomer rotates plane-polarized light by the {{c1::same magnitude}} but in the {{c2::opposite direction}} as its mirror image — a (+)-isomer at +12° pairs with a (−)-isomer at −12° under matched conditions.$praxfix$, cloze_count = 2 WHERE id = '6b06bf6a-6c37-435c-bff7-1d37b57d987a';
UPDATE public.flashcards SET cloze_text = $praxfix$To assign R or S at a chiral center: (1) {{c1::assign CIP priorities}} 1–4 to the substituents; (2) orient so the lowest-priority (4) group points {{c2::away (into the page)}}; (3) trace 1→2→3 — {{c3::clockwise = R}}, {{c3::counterclockwise = S}}.$praxfix$, cloze_count = 3 WHERE id = 'df91098a-d445-4e01-b429-6f0b22cadf78';
UPDATE public.flashcards SET cloze_text = $praxfix$In a {{c1::Fischer projection}}, the chiral carbon sits at the crossed-line intersection. Horizontal bonds project {{c2::out of the page (wedges)}}; vertical bonds project {{c3::into the page (dashes)}}. The chain runs vertically, most oxidized end at top.$praxfix$, cloze_count = 3 WHERE id = '75903915-cf7b-4f6b-a323-d31cf7cc681c';
UPDATE public.flashcards SET cloze_text = $praxfix$Conservation of {{c1::mechanical}} energy requires no non-conservative forces. The broader {{c2::first law of thermodynamics}} states that {{c3::total energy}} (mechanical + thermal + chemical + …) of an isolated system is always conserved, even when {{c1::mechanical}} energy alone is not.$praxfix$, cloze_count = 3 WHERE id = '18d7c47c-f201-4574-8211-ca66b7da2b60';
UPDATE public.flashcards SET cloze_text = $praxfix${{c1::Pierre Flourens}} was the first to systematically study the functions of major brain regions using {{c2::extirpation (ablation)}} — surgically removing parts of the brain in animals and observing the resulting behavioral deficits. His work supported {{c3::localization of function}}.$praxfix$, cloze_count = 3 WHERE id = '4b511d27-50a1-4dd7-bee9-14d4eafa8826';
UPDATE public.flashcards SET cloze_text = $praxfix$The {{c1::midbrain (mesencephalon)}} receives sensory and motor information from the rest of the body and is responsible for {{c2::involuntary reflexes}} triggered by visual or auditory stimuli.$praxfix$, cloze_count = 2 WHERE id = '6300b3c6-12b6-44d7-aa89-82d743b0cf10';
UPDATE public.flashcards SET cloze_text = $praxfix$The {{c1::hippocampus}} is critical for {{c2::learning}} and {{c3::long-term memory consolidation}}. It communicates with the rest of the limbic system through a long axonal projection called the {{c4::fornix}}.$praxfix$, cloze_count = 4 WHERE id = 'f1b25f2a-349c-4465-ae0a-10483c5fcbb7';
UPDATE public.flashcards SET cloze_text = $praxfix$The two major inhibitory neurotransmitters of the CNS are {{c1::GABA}} (primarily in the brain) and {{c2::glycine}} (primarily in the brainstem and spinal cord). Both produce {{c3::hyperpolarization}} of the postsynaptic membrane by increasing chloride influx, making the receiving neuron less likely to fire.$praxfix$, cloze_count = 3 WHERE id = 'fc413f0c-f541-499b-87d0-ceaf24d6d5fd';
UPDATE public.flashcards SET cloze_text = $praxfix$Newborn {{c1::primitive reflexes}} fade over the first year: {{c2::rooting}} = head turns to a cheek touch; {{c3::Moro}} = arms fling out when falling; {{c4::Babinski}} = toes fan when the sole is stroked; {{c5::grasping}} = fingers curl around a palmed object.$praxfix$, cloze_count = 5 WHERE id = 'ba82ebed-8846-43d1-8caf-9d03842c92c7';
UPDATE public.flashcards SET cloze_text = $praxfix$To reduce cognitive dissonance, a person typically changes an {{c1::attitude or belief}} to bring it in line with their {{c2::behavior}}.$praxfix$, cloze_count = 2 WHERE id = '3a0a1409-5583-4214-b926-689c361eae61';
UPDATE public.flashcards SET cloze_text = $praxfix${{c1::Psychophysics}} studies the quantitative relationship between a stimulus's physical {{c2::intensity}} and the subjective {{c3::sensation}} it evokes. Thresholds, the just noticeable difference, and Weber's law are all psychophysical results.$praxfix$, cloze_count = 3 WHERE id = 'eaa0a33e-3ce8-48a4-95cc-51af0287f5a6';
UPDATE public.flashcards SET cloze_text = $praxfix$Seven sensory receptor classes: {{c1::photoreceptors}} (light), {{c2::mechanoreceptors}} (pressure, movement, sound), {{c3::nociceptors}} (pain), {{c4::thermoreceptors}} (temperature), {{c5::osmoreceptors}} (blood osmolarity), {{c6::olfactory receptors}} (volatile chemicals), {{c7::taste receptors}} (dissolved chemicals).$praxfix$, cloze_count = 7 WHERE id = '98bf6226-6b48-4e1c-a415-0debb10e847d';
UPDATE public.flashcards SET cloze_text = $praxfix$At the {{c1::optic chiasm}}, only the {{c2::nasal}} retinal fibers cross to the opposite side; temporal fibers stay ipsilateral. Result: each hemisphere processes the {{c3::opposite}} visual field.$praxfix$, cloze_count = 3 WHERE id = 'a327dc2d-3276-4f94-ab02-2f3b4c48ccc5';
UPDATE public.flashcards SET cloze_text = $praxfix$The cochlea is {{c1::tonotopically}} organized: {{c2::high}}-frequency sounds vibrate the basilar membrane near the {{c3::base}} (by the oval window), while {{c2::low}}-frequency sounds vibrate it near the {{c3::apex}} (far end).$praxfix$, cloze_count = 3 WHERE id = '0bc871ea-893a-4b93-b487-cb4b74410a81';
UPDATE public.flashcards SET cloze_text = $praxfix${{c1::Motion parallax}} is the monocular cue in which, as the observer moves, {{c2::closer}} objects appear to move faster across the visual field than distant objects.$praxfix$, cloze_count = 2 WHERE id = '07724b68-92e9-46eb-8d7b-d6f804e68e30';
UPDATE public.flashcards SET cloze_text = $praxfix${{c1::Convergence}} is the second binocular depth cue: the brain detects how much the two eyes {{c2::turn inward}} to focus on an object. Greater {{c1::convergence}} means a closer object; the cue loses precision beyond a few meters.$praxfix$, cloze_count = 2 WHERE id = 'ec963441-e7cd-4728-84f7-4367535ad803';
UPDATE public.flashcards SET cloze_text = $praxfix$In {{c1::extraction}}, a mixture is shaken with {{c2::two immiscible solvents}} so the target compound concentrates in the phase where it is {{c3::more soluble}}.$praxfix$, cloze_count = 3 WHERE id = '0b45e857-ff34-4d08-97ec-7a0cd51f8c9d';
UPDATE public.flashcards SET cloze_text = $praxfix$A {{c1::rotary evaporator}} removes volatile solvent from a dissolved product by combining {{c2::reduced pressure}} with gentle warming so the solvent boils off at a {{c3::lower temperature}}.$praxfix$, cloze_count = 3 WHERE id = '50489799-7905-4d91-a5ba-4246e3b40fdb';
UPDATE public.flashcards SET cloze_text = $praxfix${{c1::Vacuum filtration}} is used when the {{c2::solid}} is the desired product; applied suction pulls the liquid through the filter quickly so the crystals {{c3::dry}} on the filter pad.$praxfix$, cloze_count = 3 WHERE id = '881adfb4-add3-4479-940f-9399146820dd';
UPDATE public.flashcards SET cloze_text = $praxfix${{c1::Aggression}} is a behavior intended to cause harm or increase {{c2::social dominance}}; most displays end with {{c3::threat and withdrawal}} rather than actual bodily harm.$praxfix$, cloze_count = 3 WHERE id = '96ea29e2-620d-4a72-8dd0-bab6ae44bdee';
UPDATE public.flashcards SET cloze_text = $praxfix$The retention factor equals the distance traveled by the {{c1::spot}} divided by the distance traveled by the {{c2::solvent front}}; values fall between {{c3::0 and 1}}.$praxfix$, cloze_count = 3 WHERE id = '00386356-7a41-46a8-9b4c-bd9ee863de59';
UPDATE public.flashcards SET cloze_text = $praxfix$In a standard column, a {{c1::nonpolar solvent}} flows down through the beads under {{c2::gravity}}, and {{c3::fractions}} are collected at the bottom as different compounds elute.$praxfix$, cloze_count = 3 WHERE id = 'c082503b-4c24-44f6-80ea-e956aa577c9f';
UPDATE public.flashcards SET cloze_text = $praxfix$α-hydrogens are unusually acidic because the {{c1::electron-withdrawing carbonyl}} weakens the C–H bond and resonance stabilizes the conjugate base (the {{c2::enolate}}).$praxfix$, cloze_count = 2 WHERE id = '69bb460e-463d-49ae-9571-bbcb225a8825';
UPDATE public.flashcards SET cloze_text = $praxfix$In {{c1::basic solution}}, balance as if acidic, then add {{c2::OH⁻}} to both sides to neutralize each {{c3::H⁺}} (forming H₂O).$praxfix$, cloze_count = 3 WHERE id = 'e66f7e35-2e0b-4383-81d7-a73eae43878a';
UPDATE public.flashcards SET cloze_text = $praxfix$An electron absorbs or emits a photon whose energy equals the difference between two energy levels, or {{c1::ΔE}}; this is why each element has a characteristic {{c2::absorption and emission spectrum}}.$praxfix$, cloze_count = 2 WHERE id = '0d37766f-61e1-4e56-873a-f00b766aea41';
UPDATE public.flashcards SET cloze_text = $praxfix${{c1::Secure attachment}} — caregiver is consistent; child explores freely and returns to the caregiver as a {{c2::secure base}}.$praxfix$, cloze_count = 2 WHERE id = 'fac757ba-cb68-4169-99d6-6af9767342c8';
UPDATE public.flashcards SET cloze_text = $praxfix$The scientific method groups 8 steps into 3 phases: ask a testable {{c1::question}} and gather data; form and test a {{c2::hypothesis}} with new data; then {{c3::publish and verify}} results.$praxfix$, cloze_count = 3 WHERE id = 'a8949dfa-6bcf-4136-8ef2-8cf2698140ce';
UPDATE public.flashcards SET cloze_text = $praxfix$A {{c1::positive control}} verifies a change occurs when expected; a {{c1::negative control}} verifies no change occurs when none is expected.$praxfix$, cloze_count = 1 WHERE id = '3c79921f-63d0-456c-998f-69c703a7340f';
UPDATE public.flashcards SET cloze_text = $praxfix$A {{c1::cross-sectional study}} measures exposure and outcome at the {{c2::same point in time}} — a single snapshot of a population.$praxfix$, cloze_count = 2 WHERE id = 'f4bb2b24-8a1e-4298-88ca-7735c7e6e1db';
UPDATE public.flashcards SET cloze_text = $praxfix$Hill's {{c1::temporality}} criterion — the {{c2::exposure}} must occur before the {{c3::outcome}} for a relationship to be considered causal.$praxfix$, cloze_count = 3 WHERE id = 'ad88f37c-5eca-4ee0-844e-7521cab8f445';
UPDATE public.flashcards SET cloze_text = $praxfix${{c1::Avoidant attachment}} — caregiver shows little response to distress; child shows {{c2::no preference}} between caregiver and stranger and {{c3::little distress}} when the caregiver leaves or returns.$praxfix$, cloze_count = 3 WHERE id = '7ee09caa-6516-4274-bdab-c6bbc72f2562';
UPDATE public.flashcards SET cloze_text = $praxfix${{c1::Nonmaleficence}} is the obligation to avoid interventions where the potential {{c2::harm}} outweighs the potential {{c3::benefit}}.$praxfix$, cloze_count = 3 WHERE id = 'e2838acc-6f9d-418b-9288-aaefecd6a71f';
UPDATE public.flashcards SET cloze_text = $praxfix${{c1::Respect for persons}} encompasses {{c2::honesty, informed consent, and confidentiality}}, and requires extra protections for {{c3::vulnerable populations}}.$praxfix$, cloze_count = 3 WHERE id = 'cdb42d22-a997-4910-8c51-681e8f40028f';
UPDATE public.flashcards SET cloze_text = $praxfix${{c1::Equipoise}} means that in a head-to-head trial comparing two treatments, researchers have {{c2::no prior knowledge}} that one option is superior.$praxfix$, cloze_count = 2 WHERE id = '8e31f6c4-edb1-4e73-94b7-181be514b89c';
UPDATE public.flashcards SET cloze_text = $praxfix${{c1::Internal validity}} establishes {{c2::cause and effect}} within the study sample; {{c3::external validity}} is whether results {{c4::generalize}} beyond the sample.$praxfix$, cloze_count = 4 WHERE id = 'da105e06-c7b8-4c36-a852-79ac1bc945f5';
UPDATE public.flashcards SET cloze_text = $praxfix${{c1::Statistical significance}} means a result is {{c2::unlikely due to chance}}; {{c3::clinical significance}} means the change is {{c4::large enough to matter}} in real-world practice.$praxfix$, cloze_count = 4 WHERE id = 'a6b21984-7193-4778-ba73-b2380b2257f6';
UPDATE public.flashcards SET cloze_text = $praxfix$A {{c1::normal distribution}} is symmetric and bell-shaped; the {{c2::mean, median, and mode}} all coincide at the center.$praxfix$, cloze_count = 2 WHERE id = '2c2ccff2-ca8c-4aa1-93dd-ac13332981d4';
UPDATE public.flashcards SET cloze_text = $praxfix$To count significant figures, count every digit from the {{c1::first nonzero digit}} to the {{c2::last nonzero digit}}; any zero between them counts.$praxfix$, cloze_count = 2 WHERE id = '0eec0201-55be-467b-8246-9ac8e276cd8b';
UPDATE public.flashcards SET cloze_text = $praxfix$In the {{c1::substitution}} method, solve one equation for one variable, then insert that expression into the other equation to reduce it to a single variable.$praxfix$, cloze_count = 1 WHERE id = 'de126799-baa7-41ea-b431-746e53b2e911';
UPDATE public.flashcards SET cloze_text = $praxfix$Setting-equations-equal method — a special case of substitution: solve both equations for the {{c1::same variable}}, then set the two expressions equal to each other.$praxfix$, cloze_count = 1 WHERE id = '60fc3d31-4693-4cff-ade6-3d4f33c11f80';
UPDATE public.flashcards SET cloze_text = $praxfix$A {{c1::bureaucracy}} is a formal organization designed to perform complex tasks efficiently, characterized by {{c2::hierarchical structure}}, {{c3::division of labor}}, and {{c4::standardized rules and procedures}}.$praxfix$, cloze_count = 4 WHERE id = '936599e2-2cd8-4911-b27a-b55fbfc74607';
UPDATE public.flashcards SET cloze_text = $praxfix${{c1::Culture}} encompasses a group's entire {{c2::lifestyle}} — both the physical things they make and the ideas they share.$praxfix$, cloze_count = 2 WHERE id = 'a509464a-adad-48c7-bf6d-31dc9795134c';
UPDATE public.flashcards SET cloze_text = $praxfix${{c1::Cultural lag}} is the phenomenon in which {{c2::symbolic}} culture lags behind {{c3::material}} culture — ideas about technology change more slowly than the technology itself.$praxfix$, cloze_count = 3 WHERE id = 'ef965b5b-a6a9-439e-930d-a9d54ee489a8';
UPDATE public.flashcards SET cloze_text = $praxfix$A {{c1::ritual}} is a formalized ceremony with specific {{c2::material objects}}, {{c3::symbolism}}, and a {{c4::set order of events}}.$praxfix$, cloze_count = 4 WHERE id = 'a329f6ca-2799-4a72-8b10-80f832d22c4e';
UPDATE public.flashcards SET cloze_text = $praxfix${{c1::Cultural transmission}} is how values, beliefs, and behaviors pass from one {{c2::generation}} to the next; {{c3::cultural barriers}} impede communication or understanding across cultures.$praxfix$, cloze_count = 3 WHERE id = '5ec4f420-98a7-4005-bca4-2556b1f53800';
UPDATE public.flashcards SET cloze_text = $praxfix$The {{c1::dependency ratio}} compares dependents — those under {{c2::15}} and over {{c3::65}} — to the working-age population (15–65).$praxfix$, cloze_count = 3 WHERE id = 'da811690-bc25-4978-b7de-44de7ebb079f';
UPDATE public.flashcards SET cloze_text = $praxfix$Demographic Transition — Stage 1 (pre-industrial): {{c1::high birth + high death}}; Stage 2: {{c2::death rate drops}}; Stage 3: {{c3::birth rate drops}}; Stage 4 (industrialized): {{c4::low birth + low death}}.$praxfix$, cloze_count = 4 WHERE id = '4bd5cfd7-10b8-4a78-bd17-ec6e7883a19b';
UPDATE public.flashcards SET cloze_text = $praxfix${{c1::Inclusive fitness}} measures reproductive success as the sum of an organism's {{c2::own offspring}} plus the offspring of {{c3::relatives}} that share its genes — explaining why altruism toward kin is favored.$praxfix$, cloze_count = 3 WHERE id = '020f188d-f362-491a-bdf6-4e9a54ccf31b';
UPDATE public.flashcards SET cloze_text = $praxfix$The {{c1::socioeconomic gradient in health}}: individuals with {{c2::lower SES}} systematically experience worse health outcomes and shorter lifespans than those with higher SES.$praxfix$, cloze_count = 2 WHERE id = '6a4cf538-947d-457d-9b2e-ed8495e0cc8d';
UPDATE public.flashcards SET cloze_text = $praxfix$Social networking creates two inequalities: {{c1::situational}} (based on {{c2::individual socioeconomic advantage}}) and {{c1::positional}} (based on {{c2::network centrality}}).$praxfix$, cloze_count = 2 WHERE id = '9b8ac526-e700-4926-a031-41fa1ba2c1fd';
UPDATE public.flashcards SET cloze_text = $praxfix${{c1::Intersectionality (Crenshaw)}} examines how {{c2::multiple, interconnected social identities}} (race, gender, class, sexuality) combine to create unique experiences of {{c3::disadvantage or privilege}}.$praxfix$, cloze_count = 3 WHERE id = '92915195-ec3e-470a-820b-6a951547389b';
UPDATE public.flashcards SET cloze_text = $praxfix${{c1::Vertical mobility}} is movement between {{c2::social classes}} (upward or downward); {{c1::horizontal mobility}} changes occupation or lifestyle but keeps you {{c3::within the same class}}.$praxfix$, cloze_count = 3 WHERE id = 'a34def4c-c548-4fb6-9dab-3459f7bc82bb';
UPDATE public.flashcards SET cloze_text = $praxfix${{c1::Poverty}} is a lack of resources to meet society's minimum standard of living; {{c2::social reproduction}} is how this inequality passes from one {{c3::generation to the next}}.$praxfix$, cloze_count = 3 WHERE id = '2d917590-53d3-4eb6-9712-2954a8af9b7e';
UPDATE public.flashcards SET cloze_text = $praxfix${{c1::Structural poverty}} blames poverty on {{c2::society's structure}}, not the actions or failings of any individual.$praxfix$, cloze_count = 2 WHERE id = '1ff9e154-3092-4861-9c0a-43a617140662';
UPDATE public.flashcards SET cloze_text = $praxfix${{c1::Suburbanization}} — middle-class migration from city centers to suburbs — can leave behind {{c2::urban decay}}, the {{c3::deterioration}} of once-functional city districts.$praxfix$, cloze_count = 3 WHERE id = '7bac2bbc-9105-48c2-99f2-12736d65d340';
UPDATE public.flashcards SET cloze_text = $praxfix$A {{c1::modern welfare state}} is a system of government that protects citizens' health and well-being through {{c2::social safety-net programs}}.$praxfix$, cloze_count = 2 WHERE id = '5cfc44a5-7b54-4106-8ca1-c7b4f2300b50';
UPDATE public.flashcards SET cloze_text = $praxfix${{c1::Spatial inequality}} is the unequal distribution of resources across territories; {{c2::residential segregation}} is the separation of ethnic or racial groups into different residential areas.$praxfix$, cloze_count = 2 WHERE id = 'bb4ba147-cf58-4f25-aca6-23f983fa78f5';
UPDATE public.flashcards SET cloze_text = $praxfix$The s orbital is {{c1::spherical}}; the p orbital is {{c2::dumbbell-shaped}} (two lobes, one node); the d orbital is {{c3::clover-shaped}} (four lobes, two nodes).$praxfix$, cloze_count = 3 WHERE id = 'cb788a21-60b5-4b0c-a773-1aacee6f2241';
UPDATE public.flashcards SET cloze_text = $praxfix$A {{c1::node}} is a region where the probability of finding an electron is {{c2::zero}}.$praxfix$, cloze_count = 2 WHERE id = '4f15a994-d219-4875-a8dd-b9698f34882c';
UPDATE public.flashcards SET cloze_text = $praxfix${{c1::Hybrid orbitals}} form by mathematically mixing one {{c2::s}} orbital with one or more {{c3::p}} orbitals into equivalent orbitals optimized for bonding.$praxfix$, cloze_count = 3 WHERE id = 'e5a77192-0f7a-4875-8825-a53a73a6b10f';
UPDATE public.flashcards SET cloze_text = $praxfix${{c1::sp³ hybridization}} mixes 1 s and 3 p orbitals into four equivalent orbitals at {{c2::109.5°}} ({{c3::tetrahedral}}); geometry of saturated carbons in {{c4::alkanes}}.$praxfix$, cloze_count = 4 WHERE id = '3229b66f-a904-484a-a104-ddff36ab3ca8';
UPDATE public.flashcards SET cloze_text = $praxfix${{c1::sp² hybridization}} mixes 1 s and 2 p orbitals into three orbitals at {{c2::120°}} ({{c3::trigonal planar}}); the remaining {{c4::unhybridized p orbital}} forms the pi bond — geometry of {{c5::alkenes}}.$praxfix$, cloze_count = 5 WHERE id = 'e8d1c714-de34-441e-96d2-7542a8d156bc';
UPDATE public.flashcards SET cloze_text = $praxfix${{c1::Resonance}} is the {{c2::delocalization}} of pi electrons or lone pairs across multiple atoms, producing extra stability.$praxfix$, cloze_count = 2 WHERE id = 'ddd8a213-1559-4953-92f6-305be384227a';
UPDATE public.flashcards SET cloze_text = $praxfix${{c1::Conjugation}} requires {{c2::alternating single and multiple bonds}}, aligning unhybridized {{c3::p orbitals}} along the molecular backbone.$praxfix$, cloze_count = 3 WHERE id = 'cfe689cc-45af-41f5-834c-961d749ee54f';
UPDATE public.flashcards SET cloze_text = $praxfix$Delocalization through conjugation {{c1::adds stability}} by spreading {{c2::electron density}} over more atoms.$praxfix$, cloze_count = 2 WHERE id = '601c7ea8-6589-46db-a40d-18ac3ccfac2d';
UPDATE public.flashcards SET cloze_text = $praxfix$Resonance forms differ only in {{c1::electron placement}}; the {{c2::atom positions}} remain fixed.$praxfix$, cloze_count = 2 WHERE id = 'f7b15bca-4020-4638-a34a-5fe7d42fecd1';
UPDATE public.flashcards SET cloze_text = $praxfix$A {{c1::coordinate covalent bond}} is a covalent bond in which both bonding electrons come from {{c2::the same atom}} — typically formed when a Lewis acid and Lewis base interact.$praxfix$, cloze_count = 2 WHERE id = '9607337d-5d2a-4e29-99fe-fdc12c8910c1';
UPDATE public.flashcards SET cloze_text = $praxfix$Four factors govern nucleophilicity: {{c1::charge}} (more negative = more nucleophilic), {{c1::electronegativity}} (lower = more nucleophilic), {{c1::steric hindrance}} (bulkier = less nucleophilic), and {{c1::solvent type}} (protic vs aprotic).$praxfix$, cloze_count = 1 WHERE id = 'd86fe6a1-d583-4f75-b0f4-cde1ba4b7274';
UPDATE public.flashcards SET cloze_text = $praxfix$Six steps to analyze an organic reaction: (1) {{c1::know your nomenclature}}, (2) {{c2::identify functional groups}}, (3) {{c3::identify other reagents}}, (4) {{c4::identify the most reactive functional groups}}, (5) {{c5::identify the first step}}, (6) {{c6::consider stereospecificity / selectivity}}.$praxfix$, cloze_count = 6 WHERE id = '5bce76fd-d144-467d-896b-813081f30776';
UPDATE public.flashcards SET cloze_text = $praxfix$Aldehydes are more reactive toward nucleophiles than ketones for two reasons: less {{c1::steric hindrance}} and fewer {{c2::electron-donating alkyl groups}} stabilizing the partial positive charge.$praxfix$, cloze_count = 2 WHERE id = 'cf81c548-d941-4b3b-87a0-a74d97bffc76';
UPDATE public.flashcards SET cloze_text = $praxfix$Imines can {{c1::tautomerize}} into {{c2::enamines}}, which contain both a {{c3::C=C double bond}} and a {{c4::nitrogen substituent}} (analogous to keto–enol tautomerization).$praxfix$, cloze_count = 4 WHERE id = '13494601-0a1b-424b-a9b4-8a3fd9984699';
UPDATE public.flashcards SET cloze_text = $praxfix$In the first step, the {{c1::nucleophile}} attacks the {{c2::carbonyl carbon}}, pushing the π electrons up onto the {{c3::oxygen}} to form an alkoxide intermediate.$praxfix$, cloze_count = 3 WHERE id = 'c5fd0e99-38da-4c0d-9344-af4fc4e06afc';
UPDATE public.flashcards SET cloze_text = $praxfix$Aldol condensations give clean products only with a {{c1::single}} type of aldehyde or ketone; two different substrates give a {{c2::mixture of products}} (can't control nucleophile vs electrophile).$praxfix$, cloze_count = 2 WHERE id = '88340369-c995-4f4f-9afa-22afcc297eb2';
UPDATE public.flashcards SET cloze_text = $praxfix$A {{c1::carboxylic acid (–COOH)}} contains a {{c2::carbonyl}} and a {{c3::hydroxyl}} group on the same carbon; it is always a {{c4::terminal}} functional group.$praxfix$, cloze_count = 4 WHERE id = '32c3b369-a813-4f52-aa1a-5688b3ef82e9';
UPDATE public.flashcards SET cloze_text = $praxfix$Carboxylic acids are excellent hydrogen bonders because both the {{c1::hydroxyl OH}} and the {{c2::carbonyl oxygen}} participate — the molecule is both a strong H-bond {{c3::donor}} and {{c4::acceptor}}.$praxfix$, cloze_count = 4 WHERE id = 'bdeff1a8-3cf4-45ef-a491-64843c902c43';
UPDATE public.flashcards SET cloze_text = $praxfix$Carboxylic acids commonly form {{c1::dimers}} (two molecules joined by {{c2::two}} hydrogen bonds); these multiple H-bonds give them higher {{c3::boiling points}} than the corresponding {{c4::alcohols}}.$praxfix$, cloze_count = 4 WHERE id = '6ee3e7c8-9b92-4574-8b39-4a96f691d795';
UPDATE public.flashcards SET cloze_text = $praxfix$In {{c1::β-dicarboxylic acids}}, the α-hydrogens between the two carboxyls are {{c2::extremely acidic}} because the resulting carbanion is stabilized by both carboxyls' {{c3::electron-withdrawing}} effect.$praxfix$, cloze_count = 3 WHERE id = '2fc9bd14-16e8-45e0-865b-9e92459a376e';
UPDATE public.flashcards SET cloze_text = $praxfix${{c1::Attribution theory}} describes how we infer the {{c2::causes}} of other people's behavior.$praxfix$, cloze_count = 2 WHERE id = '22d283e3-afea-40ad-b0d1-63b30d71487b';
UPDATE public.flashcards SET cloze_text = $praxfix$The acid catalyst in Fischer esterification protonates the {{c1::carbonyl oxygen}}, placing additional positive charge on the {{c2::carbonyl carbon}} and increasing its susceptibility to {{c3::nucleophilic attack}} by the alcohol.$praxfix$, cloze_count = 3 WHERE id = '3287f03f-a59b-4af0-87c1-c52d32575713';
UPDATE public.flashcards SET cloze_text = $praxfix$Esters are named with the {{c1::alkyl group}} from the alcohol first, then the acid name with {{c2::-oate}} replacing -oic acid. Cyclic esters are called {{c3::lactones}}.$praxfix$, cloze_count = 3 WHERE id = '3224245f-1114-4521-9e7a-00aa5a185ffe';
UPDATE public.flashcards SET cloze_text = $praxfix${{c1::Saponification}} is the reaction of a {{c2::long-chain fatty acid}} with NaOH or KOH to form a {{c3::soap}} (the carboxylate salt of the fatty acid).$praxfix$, cloze_count = 3 WHERE id = 'fba3c092-fe80-421d-b8b5-54e2cb6e8874';
UPDATE public.flashcards SET cloze_text = $praxfix${{c1::Dispositional}} (internal) attributions explain behavior by the person's traits; {{c2::situational}} (external) attributions explain it by the surrounding context.$praxfix$, cloze_count = 2 WHERE id = 'e3890c3e-011c-4970-a634-ef73898a29c4';
UPDATE public.flashcards SET cloze_text = $praxfix${{c1::Saponification}} is the base-catalyzed hydrolysis of {{c2::triglycerides}} by NaOH or KOH, producing {{c3::glycerol}} plus fatty-acid carboxylate salts ({{c4::soap}}).$praxfix$, cloze_count = 4 WHERE id = 'cfc3ab8d-2d60-4599-924d-01b319957751';
UPDATE public.flashcards SET cloze_text = $praxfix$Amides resist nucleophilic attack because the {{c1::nitrogen lone pair}} stabilizes the carbonyl by resonance, so hydrolysis requires {{c2::strong acid or base}} plus {{c3::heat}}.$praxfix$, cloze_count = 3 WHERE id = '79b8993d-dbc3-440a-88c4-7742383e6c41';
UPDATE public.flashcards SET cloze_text = $praxfix$The overall order of a reaction equals the {{c1::sum}} of the individual reactant orders; a rate law of rate = k[A]¹[B]² is therefore {{c2::third}} order overall.$praxfix$, cloze_count = 2 WHERE id = 'dd735aa6-6b54-4029-9609-04068876389c';
UPDATE public.flashcards SET cloze_text = $praxfix$A {{c1::zero}}-order reaction has rate = k, so its rate stays {{c2::constant}} regardless of reactant concentration; a plot of [A] versus t is linear with slope {{c3::−k}}, and k carries units of {{c4::M·s⁻¹}}.$praxfix$, cloze_count = 4 WHERE id = 'c42ed221-d9d3-4c0f-b37a-59158219ac06';
UPDATE public.flashcards SET cloze_text = $praxfix$An effective (reactive) collision requires both the {{c1::correct orientation}} of the colliding molecules and a collision energy at least equal to the {{c2::activation energy}}.$praxfix$, cloze_count = 2 WHERE id = 'cff23918-0f55-4ae6-be22-e6398ff6436b';
UPDATE public.flashcards SET cloze_text = $praxfix${{c1::Collision theory}} holds that molecules must physically {{c1::collide}} before they can react, and it predicts the reaction rate is proportional to the {{c2::collision frequency}}.$praxfix$, cloze_count = 2 WHERE id = '8fc570a7-25f3-4e4f-9816-eccc86097aa9';
UPDATE public.flashcards SET cloze_text = $praxfix$When reactants collide with proper orientation and adequate energy they form a short-lived {{c1::activated complex (transition state)}}, which sits at {{c2::higher}} energy than both the reactants and the products on the reaction coordinate.$praxfix$, cloze_count = 2 WHERE id = '982038d5-ba3d-403f-8a11-b7f4f3c59f25';
UPDATE public.flashcards SET cloze_text = $praxfix$When the rate-determining step is the {{c1::first}} step of a mechanism, the overall rate law is simply that step's rate law; if a fast reversible equilibrium precedes it, you must first replace any {{c2::intermediate}} concentration with reactant terms.$praxfix$, cloze_count = 2 WHERE id = '8293ecb6-ed6a-476c-8d08-5ae440573954';
UPDATE public.flashcards SET cloze_text = $praxfix${{c1::Stereotypes}} are impressions about the characteristics of members of a {{c2::group}}; their cognitive purpose is to {{c3::categorize and simplify}} a complex social world.$praxfix$, cloze_count = 3 WHERE id = 'ba831dcf-5a21-44fc-ad18-bfb8e4f8459d';
UPDATE public.flashcards SET cloze_text = $praxfix${{c1::Self-fulfilling prophecy}} — a stereotype creates expectations, and the target {{c2::conforms to}} them, confirming the stereotype.$praxfix$, cloze_count = 2 WHERE id = '71792077-8e1c-42d9-b47e-a8b552851609';
UPDATE public.flashcards SET cloze_text = $praxfix${{c1::Discrimination}} is a {{c2::behavior}} treating individuals differently by group membership; prejudice does {{c3::not always}} lead to discrimination, and discrimination can occur without prejudice.$praxfix$, cloze_count = 3 WHERE id = 'd3761687-c5e6-437e-8e74-c42ea1e37748';
UPDATE public.flashcards SET cloze_text = $praxfix$Under ΔU = Q − W, a positive W means the gas {{c1::expands}}, doing work on the surroundings.$praxfix$, cloze_count = 1 WHERE id = 'da515c20-2a9e-4902-a56e-7f2ffd4ddd5b';
UPDATE public.flashcards SET cloze_text = $praxfix$A phase change proceeds at {{c1::constant temperature}} because absorbed heat raises {{c2::potential}} energy (breaking bonds), not {{c3::kinetic}} energy.$praxfix$, cloze_count = 3 WHERE id = '1e69f6f8-90a5-4679-b41c-a9d11c2ac17f';
UPDATE public.flashcards SET cloze_text = $praxfix${{c1::Scientific notation}} writes a number as a {{c2::significand}} times 10 raised to an {{c3::exponent}} (e.g., 6.02 × 10²³).$praxfix$, cloze_count = 3 WHERE id = '9af59a8b-a013-4c9e-bb45-cd43cdaebf49';
UPDATE public.flashcards SET cloze_text = $praxfix$When a fraction is raised to an exponent, the exponent applies to both the {{c1::numerator}} and {{c2::denominator}} — (X/Y)ᴬ = Xᴬ / Yᴬ.$praxfix$, cloze_count = 2 WHERE id = 'fda7c907-c990-42ae-bbe7-7d380c8813ba';
UPDATE public.flashcards SET cloze_text = $praxfix$Gravitational potential energy near Earth's surface is {{c1::Ug = mgh}}, where m is mass, g is the acceleration due to gravity (≈ 9.8 m/s²), and h is the {{c2::height}} above a chosen reference level (the datum).$praxfix$, cloze_count = 2 WHERE id = '3be96694-994f-4700-8496-af65827174ac';
UPDATE public.flashcards SET cloze_text = $praxfix$A {{c1::box plot}} displays the five-number summary: the box spans {{c2::Q₁}} to {{c3::Q₃}}, a line marks the {{c4::median}}, and the whiskers reach the extreme values within {{c5::1.5 × IQR}}.$praxfix$, cloze_count = 5 WHERE id = '379b5969-06ef-4e2c-965f-6ff375128565';
UPDATE public.flashcards SET cloze_text = $praxfix$A {{c1::fluid}} is any substance that can flow and take the shape of its container.$praxfix$, cloze_count = 1 WHERE id = 'aa38e258-9328-4bd3-9bb7-99c56cfc4880';
UPDATE public.flashcards SET cloze_text = $praxfix$Hydrostatic pressure at a point in a static fluid is produced by the {{c1::weight}} of the fluid lying above that point.$praxfix$, cloze_count = 1 WHERE id = '2c15d847-83ce-4247-8247-06a09eb082cd';
UPDATE public.flashcards SET cloze_text = $praxfix$Kinship arises through {{c1::consanguinity}} (shared blood/descent) or {{c2::affinity}} (marriage); descent may be {{c3::patrilineal, matrilineal, or bilateral}}.$praxfix$, cloze_count = 3 WHERE id = '59983ea4-6ef5-43e0-bb24-6f9be002c718';
UPDATE public.flashcards SET cloze_text = $praxfix$Strip alveoli of surfactant and the water lining them exerts {{c1::high surface tension}}, which {{c2::collapses}} them and hinders reinflation — the failure in respiratory distress syndrome.$praxfix$, cloze_count = 2 WHERE id = 'fa7ea3ce-3f2a-4818-9f88-0bb080ea318d';
UPDATE public.flashcards SET cloze_text = $praxfix$Inspiration depends on {{c1::skeletal muscle}} contraction (diaphragm, external intercostals) enlarging the thoracic cavity; the {{c2::pleural fluid}}'s adhesive force drags the lungs open, dropping intra-alveolar pressure {{c3::below atmospheric}} so air flows in.$praxfix$, cloze_count = 3 WHERE id = '33c6c92a-cc0f-4f95-a022-bbbd22f5ad7c';
UPDATE public.flashcards SET cloze_text = $praxfix$When the diaphragm and external intercostals contract, thoracic volume rises and intra-alveolar pressure {{c1::falls below}} atmospheric, so air flows down the {{c2::pressure gradient}} into the lungs; this mechanism is called {{c3::negative-pressure breathing}}.$praxfix$, cloze_count = 3 WHERE id = 'f8fa82f4-00a4-4bf2-bc1a-70a7f28307d9';
UPDATE public.flashcards SET cloze_text = $praxfix$Automatic breathing originates in the {{c1::medulla oblongata}}, whose rhythmic neuron discharges drive the {{c2::respiratory muscles}} to contract, setting the basic rhythm of ventilation.$praxfix$, cloze_count = 2 WHERE id = '85736a70-625e-40ef-ad8a-a0c861eb2675';
UPDATE public.flashcards SET cloze_text = $praxfix$At the alveolar membrane each gas diffuses from {{c1::higher}} to {{c1::lower}} partial pressure: O₂ moves {{c2::alveolus → blood}} while CO₂ moves the {{c3::opposite}} way; though CO₂'s gradient is far smaller, it keeps pace via its greater {{c4::solubility}}.$praxfix$, cloze_count = 4 WHERE id = 'c35a5ac4-5a9d-4fd2-9090-69fbebfd7232';
UPDATE public.flashcards SET cloze_text = $praxfix$Before inhaled air reaches the mucociliary escalator, the coarse hairs of the nares — the {{c1::vibrissae (nasal hairs)}} — act as a mechanical sieve, snagging large {{c2::particulates}} (dust, dirt) that could carry pathogens deeper into the airway.$praxfix$, cloze_count = 2 WHERE id = 'a330d302-46d3-4189-8ee8-e86295ade8f6';
UPDATE public.flashcards SET cloze_text = $praxfix$Once a steroid hormone binds its intracellular receptor, the complex acts as a {{c1::transcription factor}}: docking onto a specific DNA sequence, it {{c2::up- or down-regulates}} {{c1::transcription}} of the target gene.$praxfix$, cloze_count = 2 WHERE id = 'da685aa3-1949-4644-9030-65d2e2b2cf78';
UPDATE public.flashcards SET cloze_text = $praxfix$When blood calcium climbs, the thyroid's {{c1::C (parafollicular) cells}} release calcitonin, which {{c2::lowers}} serum Ca²⁺ by {{c3::depositing it into bone}}, {{c4::reducing intestinal absorption}}, and {{c5::increasing urinary excretion}}.$praxfix$, cloze_count = 5 WHERE id = 'e84f7d06-6de8-4c7a-be06-250b8070da58';
UPDATE public.flashcards SET cloze_text = $praxfix$Pituitary {{c1::LH}} drives the {{c2::Leydig}} cells of the testes to release {{c3::testosterone}}, whose fetal surge directs {{c4::differentiation}} of the male sexual organs in utero.$praxfix$, cloze_count = 4 WHERE id = '72f06e35-cc29-4907-860d-bda146598751';
UPDATE public.flashcards SET cloze_text = $praxfix${{c1::Autonomy}} is the duty to respect a patient's own {{c2::decisions}} about their health care.$praxfix$, cloze_count = 2 WHERE id = '3fc5c06b-4954-4f00-99f2-036c61482d1d';
UPDATE public.flashcards SET cloze_text = $praxfix$The posterior pituitary makes {{c1::none}} of its own hormones; instead {{c2::hypothalamic}} neurons build ADH and oxytocin and ferry them down {{c3::axons}} for storage and release there.$praxfix$, cloze_count = 3 WHERE id = '8efa4f8f-6eb5-4e35-b1e4-116f17b20b6e';
UPDATE public.flashcards SET cloze_text = $praxfix${{c1::Retinal disparity}}, the slight difference between the images on the two retinas, is the main binocular depth cue. The {{c2::more disparate}} the images, the {{c3::closer}} the object.$praxfix$, cloze_count = 3 WHERE id = '282e7404-76cf-4e6e-8051-10eab00d24b8';
UPDATE public.flashcards SET cloze_text = $praxfix$In the ABO system, a person's plasma holds antibodies against exactly the A or B antigens their own red cells {{c1::lack}}.$praxfix$, cloze_count = 1 WHERE id = '728da572-0016-40ed-a08e-87644a92ed93';
UPDATE public.flashcards SET cloze_text = $praxfix$Passive immunity is natural when maternal antibodies cross the {{c1::placenta or breast milk}}, and artificial when immunoglobulins are {{c2::injected (IVIg)}}.$praxfix$, cloze_count = 2 WHERE id = '3883d8a2-c78b-4ce6-9744-5618b69e2210';
UPDATE public.flashcards SET cloze_text = $praxfix$The internal urethral sphincter is {{c1::smooth}} muscle under {{c2::involuntary (autonomic)}} control.$praxfix$, cloze_count = 2 WHERE id = 'd6a98e76-868d-48f8-ac06-9306db615b18';
UPDATE public.flashcards SET cloze_text = $praxfix$The external urethral sphincter is {{c1::skeletal}} muscle under {{c2::voluntary (conscious)}} control.$praxfix$, cloze_count = 2 WHERE id = '34926a72-f379-47d6-8a01-5fa8d4efb03f';
UPDATE public.flashcards SET cloze_text = $praxfix$In a hypotonic solution, a cell {{c1::gains water}}, {{c2::swells}}, and may {{c3::lyse}}.$praxfix$, cloze_count = 3 WHERE id = 'ea300dc9-6ca3-4cc9-9ce5-e9df230b2fff';
UPDATE public.flashcards SET cloze_text = $praxfix$The electrostatic (Coulomb) force between two point charges is a central force, directed along the line joining their {{c1::centers}}.$praxfix$, cloze_count = 1 WHERE id = '8d2d9326-05e3-44dc-8554-2110bdc60660';
UPDATE public.flashcards SET cloze_text = $praxfix$For a fixed amount of gas at constant temperature, {{c1::Boyle's}} law states pressure and volume are {{c2::inversely proportional}}, so {{c3::P₁V₁ = P₂V₂}}.$praxfix$, cloze_count = 3 WHERE id = 'de8936a0-f5ba-4bb8-9ed9-a5c5c354d4ad';
UPDATE public.flashcards SET cloze_text = $praxfix$For a fixed amount of gas at constant pressure, {{c1::Charles's}} law states volume and absolute temperature are {{c2::directly proportional}}, so {{c3::V₁/T₁ = V₂/T₂}}.$praxfix$, cloze_count = 3 WHERE id = 'b5391286-4118-4d19-aaab-9f5cd6ccf86f';
UPDATE public.flashcards SET cloze_text = $praxfix$For a fixed amount of gas at constant volume, {{c1::Gay-Lussac's}} law states pressure and absolute temperature are {{c2::directly proportional}}, so {{c3::P₁/T₁ = P₂/T₂}}.$praxfix$, cloze_count = 3 WHERE id = '7b4eee74-90dd-4b95-b51a-6ed1f99feefd';
UPDATE public.flashcards SET cloze_text = $praxfix$At constant temperature and pressure, {{c1::Avogadro's}} law states a gas's volume and number of moles are {{c2::directly proportional}}, so {{c3::V/n}} stays constant.$praxfix$, cloze_count = 3 WHERE id = '30c83d26-a5f4-49a7-843a-109977e5851f';
UPDATE public.flashcards SET cloze_text = $praxfix$For a fixed amount of gas compared across two states, the ideal gas law reduces to the {{c1::combined gas law}}: {{c2::P₁V₁/T₁ = P₂V₂/T₂}}.$praxfix$, cloze_count = 2 WHERE id = '591ddd59-9f50-474e-8bf0-307dd0a04868';
UPDATE public.flashcards SET cloze_text = $praxfix$An exothermic process {{c1::releases}} heat and has a {{c2::negative}} ΔH (ΔH < 0).$praxfix$, cloze_count = 2 WHERE id = '3d436cce-7099-4947-b896-d0e03e5e9a72';
UPDATE public.flashcards SET cloze_text = $praxfix$An endothermic process {{c1::absorbs}} heat and has a {{c2::positive}} ΔH (ΔH > 0).$praxfix$, cloze_count = 2 WHERE id = '2fcdeb91-cbc0-4557-88f7-0e21d96ec219';
