UPDATE public.flashcards SET cloze_text = $praxfix$Nitrate (NO₃⁻) and acetate (CH₃COO⁻) salts are {{c1::soluble}} in water, with no exceptions.$praxfix$, cloze_count = 1 WHERE id = 'db7222b2-996f-4a3d-b66c-27b44e394c3f';
