UPDATE public.flashcards SET cloze_text = $praxfix$Molarity (M) = moles of solute per liter of {{c1::solution}} (total volume after mixing, not solvent volume).$praxfix$, cloze_count = 1 WHERE id = '47f4f12b-e4fa-4c8c-9578-82eda675585c';
UPDATE public.flashcards SET cloze_text = $praxfix$Salts of basic anions (carbonates, sulfides, hydroxides) become {{c1::more}} soluble as pH drops, because acid {{c2::consumes}} the anion, pulling dissolution forward.$praxfix$, cloze_count = 2 WHERE id = 'c044cb9b-4e65-494b-bd99-6664161fb735';
UPDATE public.flashcards SET cloze_text = $praxfix$Nonvolatile solute particles crowd a solution's surface, so {{c1::vaporization slows}} while condensation stays unchanged; equilibrium settles at a lower vapor pressure.$praxfix$, cloze_count = 1 WHERE id = 'bb25af02-ac5f-4dd3-9e9b-9db24c897dfc';
