UPDATE public.flashcards SET cloze_text = $praxfix$For a dilute solution, freezing-point depression is ΔTf = {{c1::i·Kf·m}}, where Kf is the cryoscopic constant and m is molality.$praxfix$, cloze_count = 1 WHERE id = '8144cda1-9cf7-4145-a771-bffedc675b63';
