UPDATE public.flashcards SET cloze_text = $praxfix$The van't Hoff factor i equals the number of {{c1::particles}} released into solution per formula unit of solute dissolved.$praxfix$, cloze_count = 1 WHERE id = '04837e13-ab33-41c4-a8f3-4cb245a970be';
UPDATE public.flashcards SET cloze_text = $praxfix$Neuroplasticity is greatest in {{c1::early childhood}} and {{c2::declines}} with age.$praxfix$, cloze_count = 2 WHERE id = 'ca4cd269-c206-4be2-8b55-1a68d66dea86';
UPDATE public.flashcards SET cloze_text = $praxfix$The magnetic force on a moving charge always points {{c1::perpendicular}} to the plane containing v and B.$praxfix$, cloze_count = 1 WHERE id = '27fb3e5a-0f7a-46eb-ba75-7a08f149b3b8';
UPDATE public.flashcards SET cloze_text = $praxfix$A resistor is a circuit component that {{c1::slows}} the flow of electrons without stopping it.$praxfix$, cloze_count = 1 WHERE id = 'e2c50c23-007e-471e-a50a-35b9cfed537a';
UPDATE public.flashcards SET cloze_text = $praxfix$A source moving at or above {{c1::the speed of sound}} piles up its sound waves by constructive interference into a {{c2::shock wave (sonic boom)}}.$praxfix$, cloze_count = 2 WHERE id = '5b1d6bc3-c547-436b-bee4-2d93bca10b30';
UPDATE public.flashcards SET cloze_text = $praxfix$Maslow's hierarchy of needs is arranged so that more {{c1::basic}} needs must be satisfied before {{c2::higher}} needs can motivate behavior.$praxfix$, cloze_count = 2 WHERE id = '9021b301-7ad7-4363-aff5-694e49d28fa1';
UPDATE public.flashcards SET cloze_text = $praxfix$Incentive theory holds that behavior is driven by pursuing external {{c1::rewards}} and avoiding {{c2::punishments}}.$praxfix$, cloze_count = 2 WHERE id = '4f3918d5-4c9e-4953-b076-71c6045eb547';
UPDATE public.flashcards SET cloze_text = $praxfix$Sexual motivation is shaped by {{c1::hormones}} together with {{c2::social}} and {{c3::cultural}} factors.$praxfix$, cloze_count = 3 WHERE id = '52c036bf-782e-46bd-8ba9-f118389be55a';
UPDATE public.flashcards SET cloze_text = $praxfix$Sympathetic activation during an emotion produces bodily signs such as a {{c1::racing heart}}, {{c2::sweating}}, and {{c3::faster breathing}}.$praxfix$, cloze_count = 3 WHERE id = 'e0f749b4-8a45-43d5-9b4c-04debf8cdc4a';
UPDATE public.flashcards SET cloze_text = $praxfix$If stress persists into the exhaustion stage, depleted reserves leave the body vulnerable to {{c1::illness}}, {{c2::organ damage}}, and even {{c3::death}}.$praxfix$, cloze_count = 3 WHERE id = '4e114326-c77d-47dd-98a2-b72f087253b9';
UPDATE public.flashcards SET cloze_text = $praxfix$Chronic stress exacts a physiological toll, notably suppressing the {{c1::immune}} system and straining the {{c2::cardiovascular}} system.$praxfix$, cloze_count = 2 WHERE id = '28d3bbc4-0dd9-4065-9532-737ea9d9792d';
UPDATE public.flashcards SET cloze_text = $praxfix$Although every anxiety disorder involves excessive fear or anxiety, the DSM-5 distinguishes them mainly by their {{c1::trigger}} — the specific feared object or situation.$praxfix$, cloze_count = 1 WHERE id = '94d6603a-bf4c-4f38-badf-7122f09e4946';
UPDATE public.flashcards SET cloze_text = $praxfix$Separation anxiety disorder is excessive, developmentally inappropriate fear or distress over being away from one's {{c1::attachment figures}} (e.g., a parent or caregiver).$praxfix$, cloze_count = 1 WHERE id = '4715a61a-dede-400c-b1ea-7e877bbed038';
UPDATE public.flashcards SET cloze_text = $praxfix$Obsessive-compulsive personality disorder (Cluster C), unlike OCD, has no true obsessions or compulsions; its hallmark is {{c1::perfectionism}}, {{c2::rigidity}}, and preoccupation with {{c3::orderliness and control}}.$praxfix$, cloze_count = 3 WHERE id = '283de500-b757-4859-88a0-5fe78096378c';
UPDATE public.flashcards SET cloze_text = $praxfix$The {{c1::humanistic}} perspective focuses on healthy people striving toward {{c2::self-actualization}}, the realization of one's fullest potential.$praxfix$, cloze_count = 2 WHERE id = '2e16d245-12ab-4e5b-ac30-3ec74ba3d646';
UPDATE public.flashcards SET cloze_text = $praxfix$Signal detection experiments include both signal trials (stimulus present) and {{c1::catch trials}} (stimulus absent). Each trial yields one of four outcomes: {{c2::hit}}, {{c2::miss}}, {{c2::false alarm}}, or {{c2::correct negative}}.$praxfix$, cloze_count = 2 WHERE id = '981d9ae4-0b83-4d71-aba0-37ecfcefd850';

COMMIT;

